            // removed other assertion
        }
    }

    final ImageBuilder testBuilder = imageBuilder.getSubset(25, 25, 25, 25);
    for(int x=25; x<50; x++){
        for(int y=25; y<50; y++){
            final int k = testBuilder.getRGB(x-25, y-25);
