    final float[][] transformed8x8 = REFERENCE_forwardDCT(originalData8x8);
    final float[][] reversed8x8 = REFERENCE_inverseDCT(transformed8x8);
    for (int y = 0; y < 8; y++) {
        for (int x = 0; x < 8; x++) {
            assertEquals(originalData8x8[y][x], reversed8x8[y][x], 0.001);
}
}
}

